import { GameTask } from './GameTask';
import { GameStateKey } from '../states/GameStateKey';
import type { ISlotGameMain } from '../types/ISlotGameMain';
import type { GameViewAdapter } from '../ui/GameViewAdapter';

/**
 * 免費遊戲進場設置：
 * 這裡用到的方法（updateFgUi/applyGameModeUi/setTotalMultiplierLabel/resetWinBar/
 * playTransition）都同時也被 GameMain_1002 自己的生命週期方法
 * （enterGame 等）呼叫，屬於共用能力，留在 GameMain_1002 上，此處僅透過 game 呼叫。
 */
export class EnterFreeGameTask extends GameTask {
    constructor(
        private readonly game: ISlotGameMain<GameViewAdapter>,
        private readonly freeRoundsCount: number
    ) {
        super();
    }

    protected onStart(): void {
        const game = this.game;
        game.changeState(GameStateKey.FG);
        game.freeSpinsTotal = this.freeRoundsCount;
        game.freeSpinsRemaining = this.freeRoundsCount;
        game.fgTotalWin = 0;
        game.updateFgUi();
        game.applyGameModeUi(true);
        game.setTotalMultiplierLabel(0); // 累積倍率計數器歸零（prefab 預設值別漏出來）
        game.resetWinBar();
        game.playTransition('enter')
            .then(() => new Promise<void>((r) => setTimeout(r, 600)))
            .catch((error) => console.warn('[EnterFreeGameTask] failed', error))
            .finally(() => this.finish());
    }
}
