import { _decorator, Label, RichText } from "cc";
import { EventComponent } from "../events/EventComponent";
import { BASE_EVENT_TYPE, baseRuntimeEventBus } from "../events/BaseRuntimeEventBus";
import { getLocalizedString, getLocalizedStringForLanguage, loadFixedLanguage } from "./LanguageData";
const { ccclass, property, executeInEditMode, executionOrder, playOnFocus } = _decorator;

@ccclass("1002/LocalizedLabel")
@executeInEditMode
@executionOrder(-100) // 确保在其他组件之前执行
@playOnFocus
export class LocalizedLabel extends EventComponent {
    @property({ visible: false })
    private localizedKey: string = "";

    @property({ displayName: "Key", visible: true })
    public get key(): string {
        return this.localizedKey;
    }

    public set key(str: string) {
        this.setKey(str);
    }

    @property({ tooltip: "固定顯示的語言碼（例如 en），設定後不論目前語系為何都只顯示這個語言；留空則跟隨目前語系切換" })
    public fixedLanguage: string = "";

    private placeholdersForKey: string[] | null = null;
    private placeholdersForValue: string[] | null = null;

    private label: Label | RichText | null = null;

    protected override onLoad(): void {
        super.onLoad?.();
        this.label = this.getComponent(Label) || this.getComponent(RichText);

        if (!this.label) {
            console.warn(
                "LocalizedLabel: No Label, RichText or TextMeshPro component found on the node."
            );
            return;
        }

        if (this.fixedLanguage) {
            // 固定語言不跟 currentLanguage 走，不訂閱 LANGUAGE_CHANGED；語言表在載入完成前不先渲染 fallback 字串
            // 再改渲染翻譯。
            // EDITOR 在 Cocos 裡涵蓋「Editor 內 Play 模式」，不能拿來判斷是否為純場景編輯畫面，這裡照樣嘗試載入；
            // 純場景編輯畫面載入失敗時 loadFixedLanguage 內部會 catch 掉，只印一行 warn，不影響其他情境。
            loadFixedLanguage(this.fixedLanguage as Parameters<typeof loadFixedLanguage>[0]).then(() => this.updateLabel());
        } else {
            // mobx 移除計劃：語言變動已改由 baseRuntimeEventBus 通知，不再用 mobx reaction
            this.subscribeEvent(baseRuntimeEventBus, BASE_EVENT_TYPE.LANGUAGE_CHANGED, () => this.updateLabel());
            this.updateLabel(); // 等效原本 registerReactionOnEnable 的 fireImmediately: true
        }
    }

    public setKey(key: string): void {
        this.localizedKey = key;
        this.updateLabel();
    }

    public setPlaceholdersForKey(...placeholdersArray: string[]): void {
        this.placeholdersForKey = placeholdersArray;
        this.updateLabel();
    }

    public setPlaceholdersForValue(...placeholdersArray: string[]): void {
        this.placeholdersForValue = placeholdersArray;
        this.updateLabel();
    }

    public updateLabel(): void {
        if (this.label) {
            const key =
                this.placeholdersForKey?.reduce((acc, s, index) => {
                    const placeholder = `{${index}}`;
                    return acc.replace(placeholder, s);
                }, this.localizedKey) || this.localizedKey;
            let localizedString = this.fixedLanguage
                ? getLocalizedStringForLanguage(key, this.fixedLanguage as Parameters<typeof loadFixedLanguage>[0])
                : getLocalizedString(key) || key;

            this.placeholdersForValue?.forEach((s, index) => {
                const placeholder = `{${index}}`;
                localizedString = localizedString.replace(placeholder, s);
            });

            this.label.string = localizedString;
            // fixedLanguage 標籤是非同步、比場景其他內容晚渲染，這時再把 cacheMode 切成 BITMAP
            // 去搶共用點陣字圖集空間，實測會撞上 Cocos 的圖集打包 bug（glCopySubTextureCHROMIUM
            // offset overflow），字形貼圖失敗、畫面上完全不出字但 JS 端無感——維持預設 CHAR 模式避開。
            if (!this.fixedLanguage && this.label.string !== this.localizedKey) {
                this.label.cacheMode = Label.CacheMode.BITMAP;
            }
        }
    }
}
